import { Box } from "@/shared/ui/layout/Box";

export function ToggleSwitch({ on, onToggle }: { on: boolean; onToggle: () => void }) {
  return (
    <Box
      className={"toggle" + (on ? " on" : "")}
      title={on ? "enabled" : "disabled"}
      onClick={ev => { ev.stopPropagation(); onToggle(); }}
    />
  );
}
